# Lugares nuevos de Explora Sofía (todos los del itinerario que faltaban). nivel: secundario
N = [
 dict(id='justicia', nombre='Palacio de Justicia', categoria='edificio', coord=(23.31995, 42.69550),
  resumen='El gran edificio de columnas del arranque del bulevar Vitosha, con dos leones de bronce en la escalinata. Es el punto de encuentro de los paseos gratuitos por Sofía.',
  historia=['El Palacio de Justicia se construyó entre 1929 y 1940 para reunir los tribunales de la capital, y hoy es la sede del Tribunal Supremo de Casación. Es uno de los mejores ejemplos del clasicismo monumental búlgaro de entreguerras: una fachada de columnas sobre una escalinata enorme, pensada para transmitir la solidez del Estado.',
            'Los dos leones de bronce que custodian la entrada son el símbolo de Bulgaria, el mismo que aparece en el escudo nacional. A sus pies se reúnen cada día los grupos de los paseos gratuitos por la ciudad, y es uno de los puntos de cita más fáciles de encontrar del centro.']),
 dict(id='mausoleo', nombre='Emplazamiento del mausoleo de Dimitrov', categoria='monumento', coord=(23.32665, 42.69648),
  resumen='La explanada frente al antiguo Palacio Real donde estuvo, de 1949 a 1999, el mausoleo del dirigente comunista Georgi Dimitrov.',
  historia=['Cuando murió Georgi Dimitrov, el primer dirigente de la Bulgaria comunista, en julio de 1949, el régimen levantó en apenas seis días un mausoleo de mármol blanco frente al Palacio Real, a imitación del de Lenin en Moscú. Su cuerpo embalsamado se expuso allí durante cuatro décadas, y desde su tribuna los dirigentes presidían los desfiles.',
            'Tras la caída del régimen, el cuerpo se retiró en 1990 y fue enterrado. El edificio quedó vacío, cubierto de grafitis, hasta que en 1999 el gobierno decidió demolerlo. Fue más difícil de lo previsto: las primeras cargas de explosivos apenas lo movieron y hicieron falta varios intentos, ante la mirada de cientos de curiosos. Hoy solo queda la explanada, un vacío elocuente en el centro de la ciudad.']),
 dict(id='vitosha', nombre='Bulevar Vitosha', categoria='edificio', coord=(23.31960, 42.69150),
  resumen='«Vitoshka», la calle peatonal principal de Sofía, de tiendas y terrazas, con la montaña Vitosha al fondo.',
  historia=['El bulevar Vitosha une la iglesia de Santa Nedelya con el Palacio Nacional de Cultura. Desde que se hizo peatonal es el gran paseo de la ciudad: tiendas, cafés con terraza y calefactores en invierno, y el bullicio de las tardes de fin de semana.',
            'Su nombre viene de la montaña que cierra la perspectiva hacia el sur, el Vitosha, de más de dos mil doscientos metros, el pulmón de Sofía y su estación de esquí. Mirar al fondo de la calle y ver la montaña nevada es una de las imágenes más típicas de la ciudad.']),
 dict(id='mercadoaleman', nombre='Mercado navideño alemán', categoria='temporada', temporada=True, coord=(23.32575, 42.69500),
  resumen='Casetas de madera, luces y vino caliente en el Jardín de la Ciudad, frente al Teatro Nacional. Del 14 de noviembre al 21 de diciembre, de 12:00 a 22:00 aproximadamente.',
  historia=['Cada año por Navidad, el Jardín de la Ciudad, el parque más antiguo de Sofía, acoge un mercado navideño de estilo alemán, con productos artesanos, dulces, salchichas y vino caliente. Es pequeño y acogedor, y al anochecer, con el Teatro Nacional Iván Vazov iluminado detrás, es uno de los rincones más bonitos del centro.',
            'El vaso de vino caliente ronda los dos euros sesenta. Las fechas y horarios son orientativos: comprobadlos al llegar.']),
 dict(id='navidadndk', nombre='Sofia Christmas Fest (NDK)', categoria='temporada', temporada=True, coord=(23.31915, 42.68690),
  resumen='La gran feria navideña de la explanada del Palacio Nacional de Cultura, con casetas, atracciones y pista de hielo. Del 20 de noviembre al 28 de diciembre, de 11:00 a 22:00.',
  historia=['La explanada frente al Palacio Nacional de Cultura es el gran espacio de fiestas de Sofía. En Navidad se llena con el Sofia Christmas Fest: casetas de comida y regalos, atracciones, conciertos y una pista de hielo. Es más grande y más familiar que el mercado del Jardín de la Ciudad.',
            'Está junto a la estación de metro del NDK, en la línea M2, y al final del bulevar Vitosha, así que es fácil de combinar con un paseo.']),
 dict(id='pistahielo', nombre='Pista de hielo del NDK', categoria='temporada', temporada=True, coord=(23.31850, 42.68620),
  resumen='La pista de patinaje del Sofia Christmas Fest, frente al NDK. Abierta de 11:00 a 23:00 hasta el 28 de diciembre; precio no publicado, unos 5-8 € con patines.',
  historia=['La pista de hielo forma parte del Sofia Christmas Fest y es el plan navideño favorito de las familias de Sofía. Abre todos los días hasta las once de la noche, y entre semana por la tarde suele haber poca gente.',
            'El precio no está publicado; calculad entre cinco y ocho euros con el alquiler de patines.']),
 dict(id='freetour', nombre='Free Sofia Tour', categoria='visita', temporada=True, coord=(23.32015, 42.69530),
  resumen='Paseo guiado gratuito de unas dos horas por el centro, desde el Palacio de Justicia. Los sábados de diciembre hay pases en español a las 11:00, 14:30 y 18:00.',
  historia=['Lo organiza una asociación de voluntarios y recorre lo esencial del centro: las ruinas de Serdica, la Rotonda de San Jorge, Santa Nedelya, la mezquita y la sinagoga, la plaza de la Independencia y la zona de la catedral. No hace falta reservar: basta presentarse en la escalinata del Palacio de Justicia a la hora del pase.',
            'Es gratuito y al final cada uno deja la propina que considere. Los horarios cambian según la temporada: confirmadlos antes de ir.']),
 dict(id='tourcomunismo', nombre='Tour del comunismo', categoria='visita', temporada=True, coord=(23.32420, 42.69740),
  resumen='Visita guiada de pago, de 2,5 a 3 horas, sobre la Sofía comunista: la sede del Partido, el mausoleo derruido y el Monumento al Ejército Soviético. Todos los días a las 16:00, en inglés, 18 €.',
  historia=['La misma asociación del paseo gratuito organiza este recorrido por las huellas del régimen comunista que gobernó Bulgaria de 1944 a 1989: el edificio del Largo, que fue sede del Partido, la explanada donde estuvo el mausoleo de Dimitrov y el Monumento al Ejército Soviético, entre otros lugares.',
            'Es en inglés; en español solo hay visitas privadas o audioguía. Cuesta dieciocho euros por persona. Consultad el punto de encuentro al reservar.']),
 dict(id='pdv_hisar', nombre='Plovdiv: casco antiguo y Hisar Kapiya', categoria='plovdiv', coord=(24.75330, 42.15000),
  resumen='El barrio antiguo de Plovdiv, sobre tres colinas, con casas del Renacimiento búlgaro y la vieja puerta de la fortaleza.',
  historia=['Plovdiv es una de las ciudades habitadas sin interrupción más antiguas de Europa: tracia, después Filipópolis con Filipo II de Macedonia y Trimontium con los romanos. Su casco antiguo, Staria Grad, ocupa tres colinas, y Hisar Kapiya es la puerta de la antigua fortaleza, con cimientos romanos reconstruidos en época bizantina y otomana.',
            'El barrio conserva un conjunto excepcional de casas del Renacimiento Nacional búlgaro, del siglo diecinueve, cuando los comerciantes de la ciudad se enriquecieron: fachadas pintadas, pisos altos volados sobre la calle y salones con techos de madera tallada. Algunas son museos, como la casa Kuyumdzhiev, sede del Museo Etnográfico, que cierra los lunes.']),
 dict(id='pdv_nebet', nombre='Plovdiv: Nebet Tepe', categoria='plovdiv', coord=(24.75199, 42.15131),
  resumen='La colina donde nació Plovdiv: restos de murallas de varias épocas y el mejor mirador de la ciudad. Gratis.',
  historia=['En Nebet Tepe hubo un asentamiento fortificado tracio hace miles de años, y desde aquí la ciudad fue bajando hacia la llanura. Entre las rocas se ven restos de murallas tracias, romanas y bizantinas.',
            'Desde lo alto se domina el río Maritsa y la llanura de Tracia, con las demás colinas de la ciudad y, en días claros, los Ródopes al sur.']),
 dict(id='pdv_teatro', nombre='Plovdiv: Teatro Romano', categoria='plovdiv', coord=(24.75110, 42.14699),
  resumen='Teatro de principios del siglo II, de época de Trajano, para unos seis mil espectadores. Restaurado y aún en uso. Unos 3,58 €.',
  historia=['El teatro de Filipópolis se construyó en la ladera entre dos colinas a principios del siglo segundo. Sus gradas de mármol acogían representaciones, asambleas y espectáculos.',
            'Permaneció enterrado durante siglos hasta que un corrimiento de tierras lo sacó a la luz a finales de los años sesenta del siglo veinte. Restaurado, hoy acoge conciertos y óperas en verano.']),
 dict(id='pdv_kapana', nombre='Plovdiv: barrio de Kapana', categoria='plovdiv', coord=(24.74879, 42.14914),
  resumen='«La trampa»: el antiguo barrio de artesanos, hoy lleno de galerías, murales, cafés y restaurantes.',
  historia=['Kapana fue el barrio de los artesanos en época otomana, y sus callejuelas enredadas, que dan nombre al barrio, aún llevan nombres de oficios, como Zlatarska, la de los orfebres.',
            'Con la Capitalidad Europea de la Cultura de 2019 se transformó en el barrio creativo de Plovdiv, el más animado de la ciudad para comer o tomar algo.']),
 dict(id='pdv_basilica', nombre='Plovdiv: Gran Basílica del Obispo', categoria='plovdiv', coord=(24.75259, 42.14406),
  resumen='Basílica paleocristiana del siglo IV con unos 2.000 m² de mosaicos. Museo desde 2021. 7,57 €, de 9:00 a 18:00 en invierno.',
  historia=['La Gran Basílica del Obispo de Filipópolis es una de las mayores iglesias paleocristianas de los Balcanes. Excavada en las últimas décadas, se abrió como museo en 2021 bajo un edificio que la protege.',
            'Sus suelos de mosaico, en dos niveles superpuestos, muestran motivos geométricos y más de un centenar de aves, símbolo del paraíso. Se recorren desde pasarelas de cristal.']),
]
